use ana_blockchain::Transaction;
use anyhow::Result;
use serde::{Deserialize,Serialize};
use std::{collections::HashSet,env,io::{BufRead,BufReader,Write},net::{TcpListener,TcpStream},sync::{Arc,Mutex},thread};
#[derive(Serialize,Deserialize)]struct Message{kind:String,transaction:Option<Transaction>}
type Seen=Arc<Mutex<HashSet<String>>>;type Peers=Arc<Vec<String>>;
fn handle(stream:TcpStream,seen:Seen,peers:Peers){let mut line=String::new();if BufReader::new(match stream.try_clone(){Ok(s)=>s,Err(_)=>return}).read_line(&mut line).is_err(){return}let m:Message=match serde_json::from_str(&line){Ok(v)=>v,Err(_)=>return};if m.kind!="transaction"{return}if let Some(tx)=m.transaction{if tx.verify().is_err(){eprintln!("Rejected invalid signature/network");return}let id=match tx.id(){Ok(v)=>v,Err(_)=>return};if !seen.lock().map(|mut s|s.insert(id.clone())).unwrap_or(false){return}println!("Relayed tx {id}: {} -> {} ({} atomic units)",tx.from,tx.to,tx.amount);let wire=serde_json::to_string(&Message{kind:"transaction".into(),transaction:Some(tx)}).unwrap()+"\n";for p in peers.iter(){if let Ok(mut s)=TcpStream::connect(p){let _=s.write_all(wire.as_bytes());}}}}
fn main()->Result<()>{let a:Vec<String>=env::args().collect();if a.len()<2{println!("Usage: ana-node <bind-ip:port> [peer-ip:port ...]");return Ok(())}let peers:Peers=Arc::new(a.iter().skip(2).cloned().collect());let seen:Seen=Arc::new(Mutex::new(HashSet::new()));let l=TcpListener::bind(&a[1])?;println!("ANA TESTNET transaction relay on {} ({} peers)",a[1],peers.len());println!("Alpha warning: this relay does not mine blocks or confirm balances.");for s in l.incoming(){match s{Ok(s)=>{let x=seen.clone();let p=peers.clone();thread::spawn(move||handle(s,x,p));},Err(e)=>eprintln!("accept error: {e}")}}Ok(())}